create function public.import_legacy(payload jsonb) returns void language plpgsql security definer set search_path=public as $$
declare t text;keys text;begin
 foreach t in array array['projects','companies','people','project_participants','sources'] loop
   select string_agg(quote_ident(key),',') into keys from jsonb_object_keys(payload->t->0) as key;
   if keys is not null then execute format('insert into public.%I (%s) select %s from jsonb_populate_recordset(null::public.%I,$1) on conflict do nothing',t,keys,keys,t) using payload->t;end if;
 end loop;
end $$;
revoke all on function public.import_legacy(jsonb) from public,anon,authenticated;
grant execute on function public.import_legacy(jsonb) to service_role;
insert into storage.buckets(id,name,public,file_size_limit) values('specifications','specifications',false,20971520) on conflict(id) do nothing;
create policy spec_read on storage.objects for select to authenticated using(bucket_id='specifications' and public.crm_role() in ('admin','manager','viewer'));
create policy spec_write on storage.objects for insert to authenticated with check(bucket_id='specifications' and public.crm_role() in ('admin','manager') and (storage.foldername(name))[1] in (select id from public.projects));
create policy spec_delete on storage.objects for delete to authenticated using(bucket_id='specifications' and public.crm_role() in ('admin','manager'));
commit;
